-- Artisan OS 2.0 — Daily Business Workspace
-- Applied to production 2026-09-28. Marketplace records stay separate from artisan-owned business records.
begin;
create table if not exists public.artisan_business_clients (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null default auth.uid(),full_name text not null,phone text,email text,city text,address text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.artisan_business_clients enable row level security;
drop policy if exists artisan_business_clients_owner on public.artisan_business_clients;
create policy artisan_business_clients_owner on public.artisan_business_clients for all to authenticated using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create table if not exists public.artisan_business_quotes (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null default auth.uid(),client_id uuid references public.artisan_business_clients(id) on delete set null,quote_number text not null,source text not null default 'personal' check(source in ('personal','fixeo')),status text not null default 'draft' check(status in ('draft','sent','accepted','rejected','expired','cancelled')),title text not null,description text,items jsonb not null default '[]'::jsonb,subtotal numeric not null default 0 check(subtotal>=0),discount numeric not null default 0 check(discount>=0),total numeric not null default 0 check(total>=0),validity_date date,estimated_duration text,notes text,sent_at timestamptz,accepted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_user_id,quote_number));
alter table public.artisan_business_quotes enable row level security;
drop policy if exists artisan_business_quotes_owner on public.artisan_business_quotes;
create policy artisan_business_quotes_owner on public.artisan_business_quotes for all to authenticated using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create table if not exists public.artisan_business_jobs (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null default auth.uid(),client_id uuid references public.artisan_business_clients(id) on delete set null,quote_id uuid references public.artisan_business_quotes(id) on delete set null,source text not null default 'personal' check(source in ('personal','fixeo')),title text not null,status text not null default 'planned' check(status in ('planned','in_progress','completed','cancelled')),scheduled_at timestamptz,completed_at timestamptz,amount numeric check(amount is null or amount>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.artisan_business_jobs enable row level security;
drop policy if exists artisan_business_jobs_owner on public.artisan_business_jobs;
create policy artisan_business_jobs_owner on public.artisan_business_jobs for all to authenticated using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create table if not exists public.artisan_business_ledger (id uuid primary key default gen_random_uuid(),owner_user_id uuid not null default auth.uid(),job_id uuid references public.artisan_business_jobs(id) on delete set null,quote_id uuid references public.artisan_business_quotes(id) on delete set null,source text not null default 'personal' check(source in ('personal','fixeo')),entry_type text not null check(entry_type in ('income','expense')),category text not null default 'other',amount numeric not null check(amount>0),payment_method text,occurred_on date not null default current_date,note text,created_at timestamptz not null default now());
alter table public.artisan_business_ledger enable row level security;
drop policy if exists artisan_business_ledger_owner on public.artisan_business_ledger;
create policy artisan_business_ledger_owner on public.artisan_business_ledger for all to authenticated using(owner_user_id=auth.uid()) with check(owner_user_id=auth.uid());
create index if not exists artisan_business_clients_owner_idx on public.artisan_business_clients(owner_user_id,updated_at desc);
create index if not exists artisan_business_quotes_owner_idx on public.artisan_business_quotes(owner_user_id,created_at desc);
create index if not exists artisan_business_jobs_owner_idx on public.artisan_business_jobs(owner_user_id,scheduled_at);
create index if not exists artisan_business_ledger_owner_idx on public.artisan_business_ledger(owner_user_id,occurred_on desc);
grant select,insert,update,delete on public.artisan_business_clients,public.artisan_business_quotes,public.artisan_business_jobs,public.artisan_business_ledger to authenticated;
revoke all on public.artisan_business_clients,public.artisan_business_quotes,public.artisan_business_jobs,public.artisan_business_ledger from anon;
create or replace function public.artisan_business_next_quote_number() returns text language plpgsql security definer set search_path=public,pg_temp as $$ declare v_uid uuid:=auth.uid(); v_n int; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; select count(*)+1 into v_n from public.artisan_business_quotes where owner_user_id=v_uid; return 'DEV-'||to_char(current_date,'YYYY')||'-'||lpad(v_n::text,4,'0'); end $$;
revoke all on function public.artisan_business_next_quote_number() from public,anon; grant execute on function public.artisan_business_next_quote_number() to authenticated;
create or replace function public.artisan_business_accept_quote(p_quote_id uuid) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_uid uuid:=auth.uid(); v_q public.artisan_business_quotes%rowtype; v_job uuid; begin if v_uid is null then raise exception 'AUTH_REQUIRED'; end if; select * into v_q from public.artisan_business_quotes where id=p_quote_id and owner_user_id=v_uid for update; if not found then raise exception 'QUOTE_NOT_FOUND'; end if; update public.artisan_business_quotes set status='accepted',accepted_at=coalesce(accepted_at,now()),updated_at=now() where id=p_quote_id; insert into public.artisan_business_jobs(owner_user_id,client_id,quote_id,source,title,status,amount,notes) values(v_uid,v_q.client_id,v_q.id,v_q.source,v_q.title,'planned',v_q.total,v_q.description) returning id into v_job; return v_job; end $$;
revoke all on function public.artisan_business_accept_quote(uuid) from public,anon; grant execute on function public.artisan_business_accept_quote(uuid) to authenticated;
commit;